        var f=Fresh("c01-source");var old=Snap(f.Path);string runtimeDir=Path.Combine(Work,"c01-runtime");Directory.CreateDirectory(runtimeDir);using(var store=DndStore.Open(f.Path))using(var index=new RuntimeIndex(Path.Combine(runtimeDir,"index.db")))Expect(index.RebuildFrom(store)>0,"C-01 runtime index empty");
        string pipe="docseye-c01-"+Guid.NewGuid().ToString("N"),kernelDll=Path.Combine(Repo,"src","DOCSeye.Kernel","bin","Debug","net10.0","DOCSeye.Kernel.dll");var psi=new ProcessStartInfo("dotnet"){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true};psi.ArgumentList.Add(kernelDll);psi.Environment["DOCSEYE_PIPE"]=pipe;psi.Environment["PATH"]=SqliteNative+Path.PathSeparator+Environment.GetEnvironmentVariable("PATH");using(var kernel=Process.Start(psi)??throw new InvalidOperationException("C-01 kernel start failed")){var opened=Rpc(pipe,"document.open",new{path=f.Path});Expect(opened.GetProperty("writeAuthority").GetBoolean(),"C-01 kernel open nonwritable");kernel.Kill(true);kernel.WaitForExit();Expect(kernel.HasExited,"C-01 kernel did not die");}
        Directory.Delete(runtimeDir,true);string moved=Path.Combine(Work,"c01-moved.dnd");string shell=Run(Node,ShellMove,f.Path,moved);Expect(File.Exists(moved)&&!File.Exists(f.Path),"C-01 carrier move failed");int recovered;using(var s=NativeDocumentSession.Open(moved,true)){Expect(s.WriteAuthority,"C-01 artifact-only reopen nonwritable");recovered=RecoverSentinels(s.LoadState(),f.Manifest);Expect(recovered==32,"C-01 sentinel recovery !=32");}ScorePositive("P-01","C-01",recovered,32,"32 frozen sentinel identities recovered from artifact only after kernel/runtime loss and carrier move");
        var now=Snap(moved);Expect(old.FamilyId==now.FamilyId&&old.BranchId==now.BranchId&&old.RevisionId==now.RevisionId&&old.SemanticRoot==now.SemanticRoot,"C-01 identity/root changed");Pass("C-01","committed N-001 and 32 sentinels","kill kernel; delete runtime; move carrier; reopen","exact artifact-only recovery","exact artifact-only recovery",old,now,SentinelIds(f.Manifest),"native","kernel_kill/runtime_delete/carrier_move",new{sentinels="32/32",runtime_deleted=true,shelleye=JsonDocument.Parse(shell).RootElement.Clone(),identity_remints=0});
