    private void Case03()
    {
        var f=Fresh("c03");var old=Snap(f.Path);using var s=NativeDocumentSession.Open(f.Path,true);var before=s.LoadState();var duplicates=before.Objects.Values.Where(o=>!o.Retired&&o.Type=="text_block"&&o.Data.TryGetValue("text",out var t)&&Equals(t,"Identity must never follow duplicate text.")).ToArray();Expect(duplicates.Length>=2&&duplicates[0].ParentId!=duplicates[1].ParentId,"C-03 duplicate text fixture missing");var rows=before.Objects.Values.Where(o=>!o.Retired&&o.Type=="table_row"&&o.ParentId is not null).GroupBy(o=>o.ParentId).First(g=>g.Count()>=2).OrderBy(o=>o.Order).ToArray();Guid moved=duplicates[0].Id,row=rows[0].Id;var b=s.BeginTransaction();b.MoveObject(moved,duplicates[1].ParentId!.Value,0);b.ReorderObject(row,rows.Length-1);var r=s.CommitTransaction(b,s.ReadHead().RevisionId,"C-03");Expect(r.Success,"C-03 commit failed: "+r.Classification);var after=s.LoadState();Expect(after.Objects[moved].Id==moved&&after.Objects[moved].ParentId==duplicates[1].ParentId,"C-03 paragraph ID/location wrong");var rowOrderAfter=after.Objects.Values.Where(o=>!o.Retired&&o.Type=="table_row"&&o.ParentId==rows[0].ParentId).OrderBy(o=>o.Order).ThenBy(o=>Ids.Lower(o.Id),StringComparer.Ordinal).Select(o=>o.Id).ToArray();Expect(after.Objects[row].Id==row&&rowOrderAfter[^1]==row,"C-03 row ID/sibling location wrong");var now=Snap(f.Path);Pass("C-03","duplicate paragraphs and rows","move paragraph and reorder duplicate row","same moved IDs at new locations","same moved IDs at new locations",old,now,[moved,row],"native","semantic_move_and_reorder",new{paragraph_id_preserved=true,row_id_preserved=true,coordinate_match_rebinds=0});
    }
    private void Case04()
