        var f=Fresh("c04");var old=Snap(f.Path);Guid victim,replacement;RevisionHead retiredHead;using(var s=NativeDocumentSession.Open(f.Path,true)){var st=s.LoadState();var o=st.Objects.Values.First(x=>!x.Retired&&x.Type=="text_block"&&!st.Objects.Values.Any(c=>!c.Retired&&c.ParentId==x.Id)&&!st.Boundaries.Values.Any(q=>q.OwnerId==x.Id));victim=o.Id;var stale=new PortableWriteHandle(st.FamilyId,st.BranchId,victim,s.ReadHead().RevisionId);var b=s.BeginTransaction();b.RetireObject(victim,RetiredResolution.Destroyed);replacement=b.CreateObject(o.Type,o.ParentId,o.Role,new Dictionary<string,object?>(o.Data,StringComparer.Ordinal));var rr=s.CommitTransaction(b,s.ReadHead().RevisionId,"C-04-retire");Expect(rr.Success,"C-04 retire failed");retiredHead=rr.Head!;var staleResult=s.CommitObjectData(stale,new(StringComparer.Ordinal){{"text","must-not-hit-replacement"}},"C-04-stale");Expect(!staleResult.Success&&staleResult.Classification=="stale_revision","C-04 stale old handle not refused");var currentOld=new PortableWriteHandle(st.FamilyId,st.BranchId,victim,retiredHead.RevisionId);var retired=s.CommitObjectData(currentOld,new(StringComparer.Ordinal){{"text","must-not-hit-replacement"}},"C-04-retired");Expect(!retired.Success&&retired.Classification=="retired_object","C-04 retired object not refused");var mid=s.LoadState();Expect(mid.Objects[victim].Retired&&mid.Retired[victim].Resolution==RetiredResolution.Destroyed&&mid.Objects.ContainsKey(replacement)&&!mid.Objects[replacement].Retired,"C-04 retirement/replacement wrong");var gc=s.BeginTransaction();Expect(gc.GarbageCollectRetiredWitnesses(1000)==1,"C-04 lineage GC did not collect witness");var gr=s.CommitTransaction(gc,retiredHead.RevisionId,"C-04-gc");Expect(gr.Success,"C-04 GC commit failed");Expect(s.LoadState().Retired[victim].Resolution==RetiredResolution.UnknownRetired,"C-04 witness not unknown_retired");}
