    private void Case05()
    {
        var f=Fresh("c05");var old=Snap(f.Path);SemanticState source;using(var s=NativeDocumentSession.Open(f.Path,true))source=s.LoadState();Guid annotated=source.Boundaries.Values.First().OwnerId;var target=Branching.Clone(source);var originalPublic=Branching.PublicIds(target);var originalBoundaries=target.Boundaries.Keys.ToHashSet();var map1=Branching.PasteObjectSubgraph(target,source,annotated,null,true);var boundaries1=target.Boundaries.Keys.Where(x=>!originalBoundaries.Contains(x)).ToHashSet();var before2Public=Branching.PublicIds(target);var before2Boundaries=target.Boundaries.Keys.ToHashSet();var map2=Branching.PasteObjectSubgraph(target,source,annotated,null,true);var boundaries2=target.Boundaries.Keys.Where(x=>!before2Boundaries.Contains(x)).ToHashSet();Expect(map1.Values.All(x=>!originalPublic.Contains(x))&&map2.Values.All(x=>!before2Public.Contains(x))&&boundaries1.Count>0&&boundaries2.Count>0&&!boundaries1.Overlaps(boundaries2),"C-05 copy reused public IDs/boundaries");Guid parentRev=target.RevisionId;target.RevisionId=Ids.NewV4();target.Sequence++;string outp=Persist(Path.Combine(Work,"c05-result.dnd"),target,[parentRev]);var now=Snap(outp);Pass("C-05","block and duplicate-row source","within-branch deep copy twice with retained annotations","every copied occurrence/boundary ID reminted; asset digest may share","all copied object and boundary IDs reminted",old,now,map1.Values.Concat(map2.Values),"native","two_annotated_subgraph_pastes",new{copy1_objects=map1.Count,copy2_objects=map2.Count,copy1_boundaries=boundaries1.Count,copy2_boundaries=boundaries2.Count,shared_semantic_ids=0,asset_digest_set_equal=target.Assets.Keys.ToHashSet().SetEquals(source.Assets.Keys)});
    }
    private void Case06()
