    private void Case08()
    {
        var f=Fresh("c08-base");var old=Snap(f.Path);string a=Path.Combine(Work,"c08-a.dnd"),b=Path.Combine(Work,"c08-b.dnd");CopyArtifact(f.Path,a);CopyArtifact(f.Path,b);RevisionHead baseHead,ha,hb;SemanticState baseState;using(var s=NativeDocumentSession.Open(f.Path,true)){baseHead=s.ReadHead();baseState=s.LoadState();}var targets=baseState.Objects.Values.Where(o=>!o.Retired&&o.Type=="text_block").Take(2).ToArray();using(var s=NativeDocumentSession.Open(a,true)){var r=s.CommitObjectData(new(baseHead.FamilyId,baseHead.BranchId,targets[0].Id,baseHead.RevisionId),Change(targets[0],"c08","left"),"C-08-left");Expect(r.Success,"C-08 left failed");ha=r.Head!;}using(var s=NativeDocumentSession.Open(b,true)){var r=s.CommitObjectData(new(baseHead.FamilyId,baseHead.BranchId,targets[1].Id,baseHead.RevisionId),Change(targets[1],"c08","right"),"C-08-right");Expect(r.Success,"C-08 right failed");hb=r.Head!;}using(var sa=DndStore.Open(a))using(var sb=DndStore.Open(b)){var presentation=sa.PresentWith(sb);Expect(presentation.Classification=="divergent_heads"&&!presentation.CanWrite&&presentation.CommonRevisionId==baseHead.RevisionId,"C-08 divergence not detected");}
